        called.append("third")
        assert type(exc) is ValueError

    @app.route("/")
    def fails():
        raise ValueError("boom")

    rv = client.get("/")
    assert rv.status_code == 500
    assert called == ["third", "second", "first"]


def test_teardown_continues_after_teardown_raises(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    called = []

    @app.teardown_request
    def first(exc):
        called.append("first")
        raise RuntimeError("teardown failure")

    @app.teardown_request
    def second(exc):
        called.append("second")
        assert type(exc) is ValueError

    @app.route("/")
    def fails():
        raise ValueError("boom")

    with pytest.raises(BaseExceptionGroup):
        client.get("/")

    # Teardown runs in reverse registration order; "first" is registered
    # first so it runs last. Even though it raises, "second" still runs.
    assert called == ["second", "first"]

import pytest


def test_teardown_request_reverse_order_with_exception(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    app.testing = False
    called = []

    @app.teardown_request
    def teardown_first(exc):
        assert exc is not None
        called.append("first")

    @app.teardown_request
    def teardown_second(exc):
        assert exc is not None
        called.append("second")

    @app.route("/")
    def fails():
        raise ValueError("boom")

    rv = client.get("/")
    assert rv.status_code == 500
    # teardown functions run in reverse registration order (last registered
    # runs first).
    assert called == ["second", "first"]


def test_teardown_request_each_receives_view_exception(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    app.testing = False
    received = []

    @app.teardown_request
    def teardown_one(exc):
        received.append(exc)

    @app.teardown_request
    def teardown_two(exc):
        received.append(exc)

    @app.route("/")
    def fails():
        raise ValueError("boom")

    rv = client.get("/")
    assert rv.status_code == 500
    # each teardown receives the exception the view raised.
    assert len(received) == 2
    for exc in received:
        assert isinstance(exc, ValueError)
        assert exc.args == ("boom",)


def test_teardown_request_all_run_when_one_raises(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    app.testing = False
    called = []

    @app.teardown_request
    def teardown_first(exc):
        called.append("first")

    @app.teardown_request
    def teardown_raises(exc):
        called.append("raises")
        raise RuntimeError("teardown failure")

    @app.teardown_request
    def teardown_last(exc):
        called.append("last")

    @app.route("/")
    def fails():
        raise ValueError("boom")

    with pytest.raises(BaseExceptionGroup):
        client.get("/")

    # One teardown raising must not stop the remaining teardown functions.
    assert "raises" in called
    assert "first" in called
    assert "last" in called
    # All teardown functions ran, in reverse registration order.
    assert called == ["last", "raises", "first"]

import { Hono } from '../../hono'
import { MESSAGE_MATCHER_IS_ALREADY_BUILT } from '../../router'

describe('SmartRouter default app routing', () => {
  it('uses RegExpRouter for ordinary routes', async () => {
    const app = new Hono()

    app.get('/hello', (c) => c.text('hello'))
    app.get('/user/:id', (c) => c.text('user'))

    const res = await app.request('/hello')
    expect(res.status).toBe(200)
    expect(await res.text()).toBe('hello')

    expect(app.router.name).toBe('SmartRouter + RegExpRouter')
  })

  it('falls back to TrieRouter for routes RegExpRouter cannot handle', async () => {
    const app = new Hono()

    // Ambiguous routes that RegExpRouter rejects with UnsupportedPathError
    app.get('/:user/entries', (c) => c.text('user entries'))
    app.get('/entry/:name', (c) => c.text('entry'))

    const res = await app.request('/entry/entries')
    expect(res.status).toBe(200)
    expect(await res.text()).toBe('user entries')

    expect(app.router.name).toBe('SmartRouter + TrieRouter')
  })

  it('throws when adding a route after the first request', async () => {
    const app = new Hono()

    app.get('/hello', (c) => c.text('hello'))

    const res = await app.request('/hello')
    expect(res.status).toBe(200)

    expect(() => {
      app.get('/after', (c) => c.text('after'))
    }).toThrowError(MESSAGE_MATCHER_IS_ALREADY_BUILT)
  })
})
